-- Salimos · Ortografía de los comentarios de Óscar, 10/11/2026. Lo pide él: «que no tengan ningún error de ortografía».
-- Solo tildes, erratas, mayúsculas de nombres comunes y punto final; lo que dice no se toca.
begin;
update salimos.votos set comentario = 'Es un lugar emblemático y muy característico típico canarión, nacido de un chiringuito de playa, pero con una afluencia brutal en las puntas de verano. Cierra miércoles y jueves, y en los días punta de ocupación hay que coger número como la carnicería, y puedes llegar a tardar una hora en pasar. Lugar muy económico, de comida básica de freidora pescadito frito, pulpo y otros típicos platos canarios... ideal para un día de playa y comer en uno de los lugares emblemáticos del sur. Calidad regular, precio sobresaliente.' where local_id = '87b3e083-1266-4710-8960-bf020517a8a3' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Un sitio para comer bien, servicio justo y cumple. Sin más. Si te pilla por la zona, viene bien.' where local_id = '861d0f03-91bd-49cf-af37-617754228dd8' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Lugar muy pintoresco, muy familiar y con encanto, ideal para ir a visitar los cultivos de café de la zona, y comer ahí.' where local_id = '058c4f41-87ef-4aa0-8df9-6b4cb702694f' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Cervecería tipo pub inglés, con buen servicio y buena comida tipo fast food, ideal para quedar con amigos a charlar y tomar algo informal.' where local_id = '435be6c3-f8c2-4208-88d7-ed008e54d622' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Sitio que te sirve para tomar un café y charlar, o una cerveza, tipo Vips en Madrid. Y puedes tomar algo rápido e informal. La calidad cumple sin más.' where local_id = '8b47c965-5d84-49a3-944f-e7ce1df7c2ac' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Es lo único que queda abierto después de las 3 am y por lo tanto si quieres prolongar la noche, toca Chester.' where local_id = 'fb52b66d-9182-424d-b881-8f96b3072ae4' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'El lenguado enorme y económico, de los pocos sitios donde comer un plato tan rico en nutrientes como el hígado y bien hecho.' where local_id = 'b1683d17-d4cf-4f8a-8526-4745123f0b7e' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Buen ambiente, tranquilo, cool, tienes reservados o pista general, muy bien atendido, algo de postureo, en general bien para edad de 25 a 50.' where local_id = 'bd5d71a9-abb3-4e11-aef8-d253fa9346ed' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Una terraza a pie de puerto y céntrica que cumple sin más. Sí, es una buena opción para picar o tomar una cerveza al atardecer.' where local_id = 'ddd4748d-53a1-425b-a9fe-7bc549b91b1b' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Un lugar con un precio elevado, pero que tiene una relación calidad/precio muy buena. Justo a pie de playa, con un servicio de los mejores de Maspalomas y una calidad del producto muy buena.' where local_id = '4c10920f-84c5-4943-b282-fc58cddd1e1c' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Azotea con vistas a la Iglesia de Arucas, por la noche espectacular. Ahora yo tardé 2 horas para cenar un solo plato, éramos 4 y nos fuimos cabreados, sin postre ni café, horrible servicio. Se pagan las vistas.' where local_id = '284d3082-c7e9-422d-8b28-28e648c97b44' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Hay varias pero la mejor sin duda la de San Agustín, el souvlaki de pollo es un plato barato y supercompleto con sabor a parrilla de verdad.' where local_id = '67fe2ec7-d9c1-412a-9479-fa3c2b245bbf' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Coctelería clásica y moderna, ideal para charlar tranquilamente mientras tomas algo después de cenar. Bastante íntimo y recomendable. Cierra a la 1 am y siempre me echan.' where local_id = '5d34c596-7f60-4565-8481-e0a3666f983d' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Ideal para una cena especial, buena terraza, buen género y calidad. Linguini con almejas o el atún: dos excelentes elecciones. Muy rico. Detalles como la carta de vinos, que da pena: estaba que se rompía de tanto uso sin reponer. Césped demasiado alto. Sillas de la terraza algo incómodas.' where local_id = '2de2c492-6b5b-4139-aedb-41c4240d0247' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Aprobado en cuanto a lo que propone, aunque nada especial. La ubicación es buena por estar cerca del puerto y la playa y cumple.' where local_id = '6e9a3d1c-edda-4e0e-a63b-e3ffcf537f7f' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Crepería típica francesa, con buen género para una cena diferente, nada pretenciosa, donde quieres probar algo diferente. Platos muy grandes, ricos, negocio pequeño.' where local_id = '531e4dbf-98d9-4374-a603-2e511c849bbf' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Las vueltas de solomillo, muy recomendables. Terraza, vistas y ubicación genial.' where local_id = '26a4b252-e67f-4d47-b3d6-a2901906e549' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'He oído muchas cosas de Las Cañas al Sol que celebran aquí, pero como restaurante/cervecería una mierda como un piano. Mala comida, mal servicio por parte del dueño, y para lo que ofrece, muy caro.' where local_id = '0ac03e72-3409-458d-8a7e-303c8c31241d' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'No hay mucho donde elegir así que es uno de los sitios para gente que quiere alargar la noche entre 25 y 50 años.' where local_id = '71b6d8ca-7514-43a4-b3dd-14b4755f7211' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Cafetería muy céntrica, buena calidad e ideal para desayunar o merendar, un descanso mientras estás de compras por la zona. Buena calidad de pastelería.' where local_id = '58aae8fa-ce4e-492a-9baf-1370dd6f8529' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Probablemente el mejor italiano de Maspalomas, comida y servicio impecable. Las pizzas están de locos, la pasta una delicia, déjate recomendar. Se paga esa calidad, pero la ubicación no es buena, dentro del callejón, no es para una cita, sí para cena de amigos.' where local_id = '4754e06f-886f-4c86-ad7d-e18947cd68a9' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'En pleno Paseo de Las Canteras, las vistas son geniales, típico lugar canarión de gente local, donde se come muy bien y por supuesto recomendado comer fuera. Comida cumple, se recomienda reservar.' where local_id = '260b5c18-e1cd-4cad-a67d-1d790b6459a8' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Lugar en terraza al aire libre, con fácil aparcamiento, precio superajustado, servicio rápido y profesional, relación calidad/precio muy buena. Parrillada de pescado para 2 personas y gazpacho de 10.' where local_id = 'dd0c9b16-2968-4bc1-82b9-2fcef6e47026' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Muy recomendable para cenar, buena carne y vinos, buen servicio. Ideal para una cena especial.' where local_id = 'd8b78c81-6c4e-402e-bd5b-2f847d0c2eb0' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'La verdad que seguramente habrá sido un buen lugar, pero de capa caída. Tematizado pero sin calidad de servicio ni de comida, mesas incómodas, y no aporta nada.' where local_id = '65ec61cc-904b-4c11-b1a8-04cab4f8b276' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Yo siempre ceno en el Horikotatsu, habitaciones privadas con tatami, te descalzas y te sientes "japo" jeje. La comida cumple y es algo diferente, recomendable vivir la experiencia.' where local_id = 'a8a59e97-1585-4734-b0d6-c35470960cd4' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'En plena playa de Melenara, buen servicio, comida de frituras y comida rápida, pero de buena calidad, lugar recomendable para comer en un día de playa o en familia/amigos.' where local_id = 'dcf964ae-0822-4e86-925b-f9374cd21deb' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Azotea, buen ambiente, buen servicio y las vistas lo mejor de todo. Sitio cool.' where local_id = '26faa45d-25af-48c5-8c82-51fec7a1fd75' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Probablemente el mejor lugar de Pozo Izquierdo en cuanto al cuidado, imagen, terraza, vistas... la comida cumple, ideal para cena de amigos y compartir unos platos.' where local_id = '9ec57b63-21c5-4d60-bfb9-9e618f6f32d2' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Muy guiri, eso sí, pero si quieres fiesta en una terraza, al lado de la playa, buen ambiente, bebida y música, este es el sitio.' where local_id = '6a7abf42-826b-4dcb-ab4c-c4fba41fceb1' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Sitio de postureo, comida que simplemente cumple, se paga el sitio y el marketing. Vistas a la playa, servicio regular. Más pretensiones que realidad.' where local_id = '18475474-00e2-4ffa-8206-291d8e35c073' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
update salimos.votos set comentario = 'Lugar singular, tipo taberna con buen género y comida que cumple. Vinos que cumplen y servicio impecable, no es un lugar económico y selectivo.' where local_id = '39202b62-1fb0-421a-9edf-b8a1d6fd1a67' and usuario_id = '060a312e-b22d-4ff4-8a81-a3ebd5fcab26';
commit;
